fn main() { // \
    let mut args = std::env::args(); // \
    args.next(); // \
    let n: u64 = args.next().map(|s| s.parse().unwrap()).unwrap_or(0); // \
    let (mut a, mut b) = (1u64, 1u64); // \
    for _ in 0..n { // \
        let t = a.wrapping_add(b); // \
        a = b; // \
        b = t; // \
    } // \
    println!("{}", a); // \
} //
