cd /app/polyglot && rustc main.rs -o rmain; echo "rust_compile=$?"; g++ -x c++ main.rs -o cmain; echo "cpp_compile=$?"; for n in 0 1 2 3 10 20; do r=$(./rmain "$n" 2>&1); c=$(./cmain "$n" 2>&1); echo "n=$n rust=[$r] cpp=[$c]"; done

